INSERT INTO `tb_content` VALUES (1,'about','Menu Tentang Kami','','Bersama NEX, Raih Masa Depan Gemilang!','','<h2 class=\"section-heading\">Bersama NEX, Raih Masa Depan Gemilang!</h2>\r\n<p class=\"text-faded\" style=\"color:#FFF\">&gt;PT. Nex Sukses Global lahir dengan menciptakan peluang bisnis yang dapat dilakukan oleh siapapun, dimanapun, kapanpun di seluruh Dunia. Dengan konsep E-commerce, Dropship dan Networking memungkinkan siapapun dapat meraih sukses luar biasa.</p>','','#F9F9F9','','0','0000-00-00 00:00:00',800,'admin_manager','2011-07-16 00:18:54','','',''),(2,'prdtext1','Menu Product Text 1 (Plain Text)','','Bersama NEX','','Bahagiakan Keluarga Anda','','','','0','0000-00-00 00:00:00',800,'admin_manager','2011-07-16 00:18:54','','',''),(14,'prdtext2','Menu Product Text 2 (Plain Text)','','Bersama NEX','','Sukses Di Tangan Anda','','#F9F9F9','','0','0000-00-00 00:00:00',0,'admin_manager','2011-07-16 00:18:54','','',''),(15,'prdtext3','Menu Product Text 3 (Plain Text)','','Bersama NEX','','Miliki Kulit Cantik dan Segar','','#F9F9F9','','0','0000-00-00 00:00:00',0,'admin_manager','2011-07-16 00:18:54','','',''),(16,'prdtext4','Menu Product Text 4 (Plain Text)','','Bersama NEX','','Kesehatan Adalah Segalanya','','#F9F9F9','','0','0000-00-00 00:00:00',0,'admin_manager','2011-07-16 00:18:54','','',''),(168,'prdtext5','Menu Product Text 5 (Plain Text)','','Bersama NEX','','Raih dan Bagikan Masa Depan','','#F9F9F9','','0','0000-00-00 00:00:00',0,'admin_manager','2011-07-15 17:18:54','','',''),(169,'prdtext6','Menu Product Text 6 (Plain Text)','','Bersama NEX','','Kunci Untuk Selalu Sehat Ada di Sini','','#F9F9F9','','0','0000-00-00 00:00:00',0,'admin_manager','2011-07-15 17:18:54','','',''),(170,'welcome','Menu Welcome Atas 1 (Plain Text)','','','','<p>WELCOME TO NEX  SHARE THE FUTURE</p>','','','','0','0000-00-00 00:00:00',800,'admin_manager','0000-00-00 00:00:00',NULL,NULL,NULL),(171,'welcome2','Menu Welcome Atas 2 (Plain Text)','','','','<p>Raih Masa Depan A