DROP TABLE IF EXISTS `tb_trxstok`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tb_trxstok` (
  `fidsys` bigint(20) NOT NULL AUTO_INCREMENT,
  `fidpenjualan` varchar(20) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL,
  `fidseller` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '''''',
  `fidmember` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `falamatkrm` varchar(100) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `fnostockist` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `fidproduk` varchar(30) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `fjumlah` float DEFAULT '0',
  `ftanggal` datetime DEFAULT NULL,
  `fhargasat` float DEFAULT '0',
  `fsubtotal` float DEFAULT '0',
  `fsize` varchar(55) DEFAULT NULL,
  `fcolor` varchar(55) DEFAULT '0',
  `ftgltrans` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `fjenis` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '' COMMENT 'RO atau FO',
  `fjmltrans` float NOT NULL DEFAULT '0',
  `fserial` varchar(9) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `fpin` varchar(9) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `fmethod` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '',
  `fketerangan` varchar(100) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '-',
  `ftglentry` datetime DEFAULT NULL,
  `fprocessed` char(1) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL DEFAULT '1',
  `ftglprocessed` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `fkindtrx` varchar(15) DEFAULT NULL,
  PRIMARY KEY (`fidsys`),
  UNIQUE KEY `fidsys` (`fidsys`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

